/* Parse LINE webhook -> one item per message
 * Output: { userId, text, messageType, messageId, stickerPackage?, stickerId?, seq }
 */
const body = $('Webhook').first().json.body || {};
const events = Array.isArray(body.events) ? body.events : [];
const out = [];
let seq = 0;

for (const ev of events) {
  if (ev.type !== 'message' || !ev.message) { continue; }
  const userId = (ev.source && ev.source.userId) ? ev.source.userId : '';
  if (!userId) { continue; }

  const mtype = ev.message.type || 'text';
  let text = '';
  if (mtype === 'text')          { text = String(ev.message.text || '').trim(); }
  else if (mtype === 'sticker')  { text = '[เธชเธ•เธดเธเน€เธเธญเธฃเน]'; }
  else if (mtype === 'image')    { text = '[เธ เธฒเธ]'; }
  else if (mtype === 'video')    { text = '[เธงเธดเธ”เธตเนเธญ]'; }
  else if (mtype === 'audio')    { text = '[เน€เธชเธตเธขเธ]'; }
  else if (mtype === 'file')     { text = '[เนเธเธฅเน]'; }
  else if (mtype === 'location') { text = '[เธ•เธณเนเธซเธเนเธเธ—เธตเนเธ•เธฑเนเธ]'; }
  else                           { text = '[' + mtype + ']'; }
  if (!text) { continue; }

  const item = {
    userId: userId,
    text: text,
    messageType: mtype,
    messageId: ev.message.id || '',
    seq: seq++,
  };
  if (mtype === 'sticker') {
    item.stickerPackage = ev.message.packageId ? String(ev.message.packageId) : '';
    item.stickerId = ev.message.stickerId ? String(ev.message.stickerId) : '';
  }

  out.push({ json: item });
}

return out;

/* Attach mediaUrl from upload response back to original item (matched by messageId) */
const uploads = $input.all();
const parsed  = $('Parse Events').all();
const out = [];

for (const up of uploads) {
  const j = up.json || {};
  const src = parsed.find(p => p.json.messageId === j.messageId) || { json: {} };
  const s = src.json || {};
  const url = j.url || '';
  out.push({ json: {
    userId: s.userId || '',
    text: s.text || '',
    messageType: s.messageType || 'image',
    messageId: s.messageId || j.messageId || '',
    seq: (typeof s.seq === 'number') ? s.seq : 0,
    mediaUrl: url,
    mediaPreviewUrl: url || j.previewImageUrl || '',
  } });
}

return out;

/* Forward to ChatDesk incoming.php, carrying media fields for image/video/sticker */
const cfg      = $('Set Config').first().json;
const events   = $('Merge').all();      // merged items (in merge order)
const profiles = $input.all();          // getProfile output, 1:1 with merge order

const out = [];

for (let i = 0; i < events.length; i++) {
  const ev = events[i].json || {};
  const pr = (profiles[i] && profiles[i].json) ? profiles[i].json : {};
  const profile = (pr.success && pr.profile) ? pr.profile : {};
  const displayName = profile.displayName || '';
  const pictureUrl  = profile.pictureUrl || '';

  let botEnabled = true;
  const payload = {
    userId: ev.userId,
    text: ev.text,
    sender: 'customer',
    messageId: ev.messageId,
    messageType: ev.messageType,
  };
  if (ev.mediaUrl) {
    payload.mediaUrl = ev.mediaUrl;
    payload.mediaPreviewUrl = ev.mediaPreviewUrl || ev.mediaUrl;
  }
  if (ev.stickerPackage && ev.stickerId) {
    payload.stickerPackage = ev.stickerPackage;
    payload.stickerId = ev.stickerId;
  }
  if (displayName) { payload.displayName = displayName; }
  if (pictureUrl)  { payload.pictureUrl = pictureUrl; }
  if (cfg.CHATDESK_SECRET) { payload.secret = cfg.CHATDESK_SECRET; }

  try {
    const res = await this.helpers.httpRequest({
      method: 'POST', url: cfg.CHATDESK_URL, json: true, timeout: 20000, body: payload,
    });
    botEnabled = !(res && res.botEnabled === false);
  } catch (err) {
    botEnabled = true;
  }

  out.push({ json: {
    userId: ev.userId,
    text: ev.text,
    displayName: displayName,
    botEnabled: botEnabled,
    isText: ev.messageType === 'text',
  } });
}

return out;

/* Take AI Agent output, strip thinking tags, attach userId from Send to ChatDesk */
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  let userId = '';
  try {
    userId = $('Send to ChatDesk').itemMatching(i).json.userId || '';
  } catch (err) {
    userId = '';
  }

  const raw = items[i].json.output || items[i].json.text || '';
  const replyText = String(raw).replace(/<think>[\s\S]*?<\/think>/g, '').trim();

  if (userId && replyText) {
    out.push({ json: { userId: userId, replyText: replyText } });
  }
}

return out;

/* Save bot reply into ChatDesk so it shows in agent inbox */
const cfg = $('Set Config').first().json;

for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.userId || !j.replyText) { continue; }
  const payload = { userId: j.userId, text: j.replyText, sender: 'bot' };
  if (cfg.CHATDESK_SECRET) { payload.secret = cfg.CHATDESK_SECRET; }
  try {
    await this.helpers.httpRequest({
      method: 'POST', url: cfg.CHATDESK_URL, json: true, timeout: 20000, body: payload,
    });
  } catch (err) { /* ignore */ }
}

return $input.all();
